function gerarCodigoConvite(nome) {
  const slug = nome.trim().toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 10) || "TURMA";
  const sufixo = Math.floor(100 + Math.random() * 900);
  return `${slug}${sufixo}`;
}

