function calcularInfoLiturgica(date = new Date()) {
  const year = date.getFullYear();
  const easter = easterDate(year);
  const easterPrevYear = easterDate(year - 1);
  const easterNextYear = easterDate(year + 1);

  const ashWednesday = addDays(easter, -46);
  const palmSunday = addDays(easter, -7);
  const holyThursday = addDays(easter, -3);
  const goodFriday = addDays(easter, -2);
  const holySaturday = addDays(easter, -1);
  const pentecost = addDays(easter, 49);

  // 1º Domingo do Advento deste ano civil (Advento que leva ao Natal deste ano)
  const dec24 = new Date(year, 11, 24);
  const fourthAdvent = addDays(dec24, -dec24.getDay());
  const firstAdventThisYear = addDays(fourthAdvent, -21);
  // Advento do ano civil anterior (que abriu o ano litúrgico em que estamos, se ainda não chegou dezembro)
  const dec24Prev = new Date(year - 1, 11, 24);
  const fourthAdventPrev = addDays(dec24Prev, -dec24Prev.getDay());
  const firstAdventPrev = addDays(fourthAdventPrev, -21);

  const baptismOfLord = addDays(new Date(year, 0, 6), (7 - new Date(year, 0, 6).getDay()) % 7 || 7);
  const baptismOfLordPrev = addDays(new Date(year, 0, 6), 0); // aproximação simples

  let tempo = "Tempo Comum";
  if (date >= holyThursday && date <= holySaturday) tempo = "Tríduo Pascal";
  else if (date >= ashWednesday && date < holyThursday) tempo = "Quaresma";
  else if (date > easter || sameDay(date, easter)) {
    if (date <= pentecost) tempo = "Tempo Pascal";
  }
  if (date >= firstAdventThisYear && date <= new Date(year, 11, 24)) tempo = "Advento";
  if ((date >= new Date(year, 11, 25) && date.getFullYear() === year) || (date <= new Date(year, 0, 12))) {
    if (date >= new Date(year, 11, 25) || date <= new Date(year, 0, 12)) tempo = "Tempo do Natal";
  }

  // Ano litúrgico (A/B/C): baseado no ano em que o Advento em curso termina.
  const emAdventoOuDezembroFinal = date >= firstAdventThisYear;
  const anoTermino = emAdventoOuDezembroFinal ? year + 1 : year;
  const mod = anoTermino % 3;
  const anoLetra = mod === 1 ? "A" : mod === 2 ? "B" : "C";
  const evangelistaDoAno = anoLetra === "A" ? "Mateus" : anoLetra === "B" ? "Marcos" : "Lucas";

  // Ciclo das leituras feriais (I/II): segue o ano civil — ímpar = I, par = II
  const cicloFerial = year % 2 === 0 ? "II" : "I";

  const weekday = date.getDay(); // 0=domingo ... 5=sexta
  const isAshWednesday = sameDay(date, ashWednesday);
  const isGoodFriday = sameDay(date, goodFriday);
  const isFridayInLent = weekday === 5 && date > ashWednesday && date < holyThursday && !isGoodFriday;

  let abstinencia;
  if (isAshWednesday || isGoodFriday) {
    abstinencia = { obrigatoria: true, texto: "Jejum e abstinência de carne (dia de penitência obrigatória: jejum para 18–59 anos, abstinência para maiores de 14 anos)." };
  } else if (isFridayInLent) {
    abstinencia = { obrigatoria: true, texto: "Abstinência de carne — sexta-feira da Quaresma." };
  } else if (weekday === 5) {
    abstinencia = { obrigatoria: false, texto: "Fora da Quaresma, a sexta-feira segue sendo dia de penitência; a abstinência de carne pode ser substituída por outra prática penitencial conforme orientação da paróquia." };
  } else {
    abstinencia = { obrigatoria: false, texto: "Sem obrigação de abstinência hoje." };
  }

  const fixo = SANTORAL_FIXO[mdKey(date)] || null;

  return {
    tempo, anoLetra, evangelistaDoAno, cicloFerial, abstinencia, fixo,
    isDomingo: weekday === 0,
    datasReferencia: { easter, ashWednesday, pentecost, firstAdventThisYear },
  };
}

const SEASON_CORES = {
  "Tempo do Natal": "#F2C94C",
  "Tempo Comum": "#2E9E64",
  "Quaresma": "#4A3B8C",
  "Tríduo Pascal": "#E63946",
  "Tempo Pascal": "#E9D28A",
  "Advento": "#7A1F5C",
};

function dayOfYear(date) {
  const start = new Date(date.getFullYear(), 0, 0);
  return Math.floor((date - start) / 86400000);
}

function calcularSegmentosAno(year, referenceDate) {
  const easter = easterDate(year);
  const ashWednesday = addDays(easter, -46);
  const holyThursday = addDays(easter, -3);
  const holySaturday = addDays(easter, -1);
  const pentecost = addDays(easter, 49);
  const dec24 = new Date(year, 11, 24);
  const fourthAdvent = addDays(dec24, -dec24.getDay());
  const firstAdvent = addDays(fourthAdvent, -21);
  const jan1 = new Date(year, 0, 1);
  const jan12 = new Date(year, 0, 12);
  const dec25 = new Date(year, 11, 25);
  const dec31 = new Date(year, 11, 31);

  const brutos = [
    { nome: "Tempo do Natal", inicio: jan1, fim: jan12 },
    { nome: "Tempo Comum", inicio: addDays(jan12, 1), fim: addDays(ashWednesday, -1) },
    { nome: "Quaresma", inicio: ashWednesday, fim: addDays(holyThursday, -1) },
    { nome: "Tríduo Pascal", inicio: holyThursday, fim: holySaturday },
    { nome: "Tempo Pascal", inicio: easter, fim: pentecost },
    { nome: "Tempo Comum", inicio: addDays(pentecost, 1), fim: addDays(firstAdvent, -1) },
    { nome: "Advento", inicio: firstAdvent, fim: dec24 },
    { nome: "Tempo do Natal", inicio: dec25, fim: dec31 },
  ].filter((s) => s.inicio <= s.fim);

  const totalDias = dayOfYear(dec31);
  const segmentos = brutos.map((s) => ({
    ...s,
    cor: SEASON_CORES[s.nome],
    inicioDia: dayOfYear(s.inicio),
    fimDia: dayOfYear(s.fim),
    larguraPct: ((dayOfYear(s.fim) - dayOfYear(s.inicio) + 1) / totalDias) * 100,
  }));
  const marcadorPct = (dayOfYear(referenceDate) / totalDias) * 100;
  const datasChave = [
    { nome: "Quarta-feira de Cinzas", data: ashWednesday },
    { nome: "Domingo de Páscoa", data: easter },
    { nome: "Pentecostes", data: pentecost },
    { nome: "1º Domingo do Advento", data: firstAdvent },
    { nome: "Natal", data: dec25 },
  ];
  return { segmentos, marcadorPct, totalDias, datasChave };
}

export default function App() {
  const [tab, setTab] = useState("inicio");
  const [data, setData] = useState(null);
  const [users, setUsers] = useState(null);
  const [turmas, setTurmas] = useState(null);
  const [turmaAtualId, setTurmaAtualId] = useState(null);
  const [session, setSession] = useState(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [loading, setLoading] = useState(true);
  const [saveError, setSaveError] = useState(false);

  // Observa o login do Firebase. Quando alguém entra, escuta o próprio perfil em tempo real
  // (isso evita problemas de tempo logo após o cadastro, quando o perfil acaba de ser criado)
  // e carrega turmas e usuários do Firestore.
  useEffect(() => {
    let unsubscribeMe = () => {};
    const unsubscribeAuth = onAuthStateChanged(auth, (fbUser) => {
      unsubscribeMe();
      if (!fbUser) {
        setSession(null);
        setUsers(null);
        setTurmas(null);
        setTurmaAtualId(null);
        setAuthChecked(true);
        return;
      }
      unsubscribeMe = onSnapshot(doc(db, "usuarios", fbUser.uid), async (meSnap) => {
        if (!meSnap.exists()) {
          setAuthChecked(true);
          return;
        }
        const me = meSnap.data();
        setSession({ id: fbUser.uid, nome: me.nome, papel: me.papel });
        try {
          const [turmasSnap, usuariosSnap] = await Promise.all([
            getDocs(collection(db, "turmas")),
            getDocs(collection(db, "usuarios")),
          ]);
          let loadedTurmas = turmasSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
          if (loadedTurmas.length === 0) {
            loadedTurmas = seedTurmas();
            await Promise.all(loadedTurmas.map((t) => setDoc(doc(db, "turmas", t.id), t)));
          }
          setTurmas(loadedTurmas);
          setUsers(usuariosSnap.docs.map((d) => ({ id: d.id, ...d.data() })));
          setTurmaAtualId((prev) => prev || (me.papel === "aluno" && me.turmaId ? me.turmaId : loadedTurmas[0]?.id || null));
        } catch (err) {
          console.error(err);
        } finally {
          setAuthChecked(true);
        }
      });
    });
    return () => {
      unsubscribeMe();
      unsubscribeAuth();
    };
  }, []);

  // Carrega os dados (encontros/materiais/avisos/posts) da turma selecionada sempre que ela mudar.
  useEffect(() => {
    if (!turmaAtualId) return;
    (async () => {
      setLoading(true);
      try {
        const snap = await getDoc(doc(db, "turmaData", turmaAtualId));
        let loadedData;
        if (snap.exists()) {
          loadedData = snap.data();
        } else if (turmaAtualId === "t1") {
          loadedData = seedData();
          await setDoc(doc(db, "turmaData", turmaAtualId), loadedData);
        } else {
          loadedData = dadosVazios();
          await setDoc(doc(db, "turmaData", turmaAtualId), loadedData);
        }
        setData(loadedData);
      } catch {
        setData(turmaAtualId === "t1" ? seedData() : dadosVazios());
      } finally {
        setLoading(false);
      }
    })();
  }, [turmaAtualId]);

  const persist = useCallback(async (next) => {
    setData(next);
    try {
      await setDoc(doc(db, "turmaData", turmaAtualId), next);
      setSaveError(false);
    } catch {
      setSaveError(true);
    }
  }, [turmaAtualId]);

  const persistUsers = useCallback(async (next) => {
    // Só grava no Firestore quem realmente mudou (evita tentar escrever no perfil de
    // outra pessoa, o que as regras de segurança bloqueiam — cada um só edita o próprio perfil).
    const alterados = next.filter((u) => {
      const anterior = users?.find((x) => x.id === u.id);
      return !anterior || JSON.stringify(anterior) !== JSON.stringify(u);
    });
    setUsers(next);
    try {
      await Promise.all(alterados.map((u) => setDoc(doc(db, "usuarios", u.id), u)));
      setSaveError(false);
    } catch {
      setSaveError(true);
    }
  }, [users]);

  const persistTurmas = useCallback(async (next) => {
    setTurmas(next);
    try {
      await Promise.all(next.map((t) => setDoc(doc(db, "turmas", t.id), t)));
      setSaveError(false);
    } catch {
      setSaveError(true);
    }
  }, []);

  const criarTurma = async (nome) => {
    const nova = { id: `turma-${Date.now()}`, nome: nome.trim(), criadaEm: todayISO(), codigoConvite: gerarCodigoConvite(nome) };
    await persistTurmas([...(turmas || []), nova]);
    setTurmaAtualId(nova.id);
    return nova;
  };

  const renomearTurma = async (turmaId, novoNome) => {
    if (!novoNome.trim()) return;
    const next = (turmas || []).map((t) => (t.id === turmaId ? { ...t, nome: novoNome.trim() } : t));
    await persistTurmas(next);
  };

  // Marca Avisos/Comunidade como visitados (para o contador de novidades) quando a pessoa entra na aba.
  useEffect(() => {
    if (!session || !users) return;
    if (tab !== "avisos" && tab !== "comunidade") return;
    const agora = new Date().toISOString();
    const meu = users.find((u) => u.id === session.id);
    if (meu) {
      const next = users.map((u) =>
        u.id === meu.id ? { ...u, ultimaVisita: { ...(u.ultimaVisita || {}), [tab]: agora } } : u
      );
      persistUsers(next);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab]);

  if (!authChecked || (session && (loading || !data || !users || !turmas))) {
    return (
      <div style={styles.loadingScreen}>
        <StyleSheet />
        <img src={APP_ICON} alt="Emaús" style={styles.loadingIcon} />
        <p style={{ fontFamily: "'Karla', sans-serif", color: "#2E2417", marginTop: 12 }}>
          Preparando a jornada…
        </p>
      </div>
    );
  }

  if (!session) {
    return (
      <div style={styles.app}>
        <StyleSheet />
        <LoginScreen />
      </div>
    );
  }

  const role = session.papel;
  const effectiveSession = session;
  const meuUsuario = users.find((u) => u.id === effectiveSession.id);
  const ultimaVisita = meuUsuario?.ultimaVisita || {};
  const novosAvisos = (data.avisos || []).filter((a) => !ultimaVisita.avisos || a.data > ultimaVisita.avisos).length;
  const novosPosts = (data.posts || []).filter((p) => !ultimaVisita.comunidade || p.criadoEm > ultimaVisita.comunidade).length;

  const tabs = [
    { id: "inicio", label: "Início", icon: Flame },
    { id: "liturgia", label: "Liturgia", icon: Sun },
    { id: "cronograma", label: "Caminhada", icon: Calendar },
    { id: "material", label: "Material", icon: BookOpen },
    { id: "caminhada", label: role === "catequista" ? "Turma" : "Minha Caminhada", icon: Compass },
    { id: "avisos", label: "Avisos", icon: Bell, badge: novosAvisos },
    { id: "comunidade", label: "Comunidade", icon: MessageCircle, badge: novosPosts },
  ];

  return (
    <div style={styles.app}>
      <StyleSheet />
      <Header
        session={effectiveSession}
        onLogout={() => signOut(auth)}
        tab={tab}
        setTab={setTab}
        tabs={tabs}
        previewRole={null}
        setPreviewRole={() => {}}
        role={role}
        turmas={turmas}
        turmaAtualId={turmaAtualId}
        setTurmaAtualId={setTurmaAtualId}
        criarTurma={criarTurma}
        renomearTurma={renomearTurma}
      />
      <main style={styles.main}>
        {saveError && (
          <div style={styles.errorBanner}>Não foi possível salvar agora. Tente novamente em instantes.</div>
        )}
        {tab === "inicio" && <Inicio data={data} setTab={setTab} />}
        {tab === "liturgia" && <Liturgia role={role} />}
        {tab === "cronograma" && <Cronograma data={data} persist={persist} role={role} session={effectiveSession} />}
        {tab === "material" && <Material data={data} persist={persist} role={role} session={effectiveSession} />}
        {tab === "caminhada" && (
          <Caminhada users={users} persistUsers={persistUsers} session={effectiveSession} data={data} persist={persist} turmaAtualId={turmaAtualId} turmas={turmas} />
        )}
        {tab === "avisos" && <Avisos data={data} persist={persist} role={role} />}
        {tab === "comunidade" && <Comunidade data={data} persist={persist} role={role} session={effectiveSession} users={users} turmaAtualId={turmaAtualId} />}
      </main>
      <footer style={styles.footer}>
        <span style={{ fontFamily: "'Courier Prime', monospace", fontSize: 12, letterSpacing: "0.05em" }}>
          EMAÚS · CATEQUESE DE ADULTOS
        </span>
      </footer>
    </div>
  );
}

function traduzErroFirebase(err) {
  const code = err?.code || "";
  if (code.includes("email-already-in-use")) return "Já existe uma conta com esse e-mail.";
  if (code.includes("invalid-email")) return "E-mail inválido.";
  if (code.includes("weak-password")) return "Senha muito fraca — use pelo menos 6 caracteres.";
  if (code.includes("user-not-found") || code.includes("wrong-password") || code.includes("invalid-credential")) return "E-mail ou senha incorretos.";
  if (code.includes("too-many-requests")) return "Muitas tentativas seguidas. Aguarde um pouco e tente de novo.";
  if (code.includes("network-request-failed")) return "Falha de conexão. Verifique sua internet.";
  return "Algo deu errado. Tente novamente.";
}

function LoginScreen() {
  const [mode, setMode] = useState("entrar");
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmar, setConfirmar] = useState("");
  const [codigo, setCodigo] = useState("");
  const [codigoTurma, setCodigoTurma] = useState("");
  const [erro, setErro] = useState("");
  const [carregando, setCarregando] = useState(false);
  const [turmas, setTurmas] = useState(null);

  const [recEmail, setRecEmail] = useState("");
  const [recEnviado, setRecEnviado] = useState(false);

  // Busca a lista de turmas (nome + código de convite) já na tela de login,
  // pois o cadastro de aluno precisa validar o código antes de criar a conta.
  useEffect(() => {
    getDocs(collection(db, "turmas"))
      .then((snap) => setTurmas(snap.docs.map((d) => ({ id: d.id, ...d.data() }))))
      .catch(() => setTurmas([]));
  }, []);

  const entrar = async () => {
    setErro("");
    if (!email.trim() || !senha) {
      setErro("Preencha e-mail e senha.");
      return;
    }
    setCarregando(true);
    try {
      await signInWithEmailAndPassword(auth, email.trim(), senha);
    } catch (err) {
      setErro(traduzErroFirebase(err));
    } finally {
      setCarregando(false);
    }
  };

  const cadastrar = async () => {
    setErro("");
    if (!nome.trim() || !email.trim() || !senha) {
      setErro("Preencha nome, e-mail e senha.");
      return;
    }
    if (senha !== confirmar) {
      setErro("As senhas não conferem.");
      return;
    }
    if (senha.length < 6) {
      setErro("A senha precisa ter pelo menos 6 caracteres.");
      return;
    }
    const papel = codigo.trim() === CODIGO_CATEQUISTA ? "catequista" : "aluno";
    let turmaId = null;
    if (papel === "aluno") {
      const turma = (turmas || []).find((t) => t.codigoConvite?.toUpperCase() === codigoTurma.trim().toUpperCase());
      if (!turma) {
        setErro("Código da turma inválido. Confira com a catequista.");
        return;
      }
      turmaId = turma.id;
    }
    setCarregando(true);
    try {
      const cred = await createUserWithEmailAndPassword(auth, email.trim(), senha);
      await updateProfile(cred.user, { displayName: nome.trim() });
      await setDoc(doc(db, "usuarios", cred.user.uid), {
        nome: nome.trim(),
        email: email.trim(),
        papel,
        turmaId,
        caminhada: papel === "aluno" ? caminhadaVazia() : null,
      });
    } catch (err) {
      setErro(traduzErroFirebase(err));
      setCarregando(false);
    }
  };

  const enviarRecuperacao = async () => {
    setErro("");
    if (!recEmail.trim()) {
      setErro("Digite seu e-mail.");
      return;
    }
    setCarregando(true);
    try {
      await sendPasswordResetEmail(auth, recEmail.trim());
      setRecEnviado(true);
    } catch (err) {
      setErro(traduzErroFirebase(err));
    } finally {
      setCarregando(false);
    }
  };

  if (mode === "recuperar") {
    return (
      <div style={styles.loginWrap}>
        <div style={styles.loginCard}>
          <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
            <img src={APP_ICON} alt="Emaús" style={styles.brandIcon} />
            <span style={styles.brandText}>Emaús</span>
          </div>
          <p style={styles.loginSubtitle}>Recuperar senha</p>

          {recEnviado ? (
            <p style={styles.cardBody}>
              Enviamos um link para <strong>{recEmail}</strong>. Abra seu e-mail e siga as instruções para criar uma nova senha.
            </p>
          ) : (
            <>
              <div style={styles.formRow}>
                <label style={styles.label}>E-mail</label>
                <input type="email" style={styles.input} value={recEmail} onChange={(e) => setRecEmail(e.target.value)} placeholder="seu@email.com" />
              </div>
              {erro && <p style={styles.loginErro}>{erro}</p>}
              <button style={styles.loginButton} disabled={carregando} onClick={enviarRecuperacao}>
                {carregando ? "Enviando..." : "Enviar link por e-mail"}
              </button>
            </>
          )}

          <button
            style={{ ...styles.linkButton, marginTop: 10 }}
            onClick={() => { setMode("entrar"); setErro(""); setRecEnviado(false); }}
          >
            ← Voltar para o login
          </button>
        </div>
      </div>
    );
  }

  return (
    <div style={styles.loginWrap}>
      <div style={styles.loginCard}>
        <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 6 }}>
          <img src={APP_ICON} alt="Emaús" style={styles.brandIcon} />
          <span style={styles.brandText}>Emaús</span>
        </div>
        <p style={styles.loginSubtitle}>Catequese de adultos</p>

        <div style={styles.loginTabs}>
          <button
            style={{ ...styles.loginTabButton, ...(mode === "entrar" ? styles.loginTabButtonActive : {}) }}
            onClick={() => { setMode("entrar"); setErro(""); }}
          >
            Entrar
          </button>
          <button
            style={{ ...styles.loginTabButton, ...(mode === "cadastrar" ? styles.loginTabButtonActive : {}) }}
            onClick={() => { setMode("cadastrar"); setErro(""); }}
          >
            Criar conta
          </button>
        </div>

        {mode === "cadastrar" && (
          <div style={styles.formRow}>
            <label style={styles.label}>Nome</label>
            <input style={styles.input} value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Seu nome" />
          </div>
        )}
        <div style={styles.formRow}>
          <label style={styles.label}>E-mail</label>
          <input type="email" style={styles.input} value={email} onChange={(e) => setEmail(e.target.value)} placeholder="seu@email.com" />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Senha</label>
          <input type="password" style={styles.input} value={senha} onChange={(e) => setSenha(e.target.value)} placeholder="••••••••" />
        </div>

        {mode === "entrar" && (
          <button style={styles.linkButton} onClick={() => { setMode("recuperar"); setErro(""); setRecEmail(email); setRecEnviado(false); }}>
            Esqueci minha senha
          </button>
        )}

        {mode === "cadastrar" && (
          <>
            <div style={styles.formRow}>
              <label style={styles.label}>Confirmar senha</label>
              <input type="password" style={styles.input} value={confirmar} onChange={(e) => setConfirmar(e.target.value)} />
            </div>
            <div style={styles.formRow}>
              <label style={styles.label}>Código da turma</label>
              <input
                style={styles.input}
                value={codigoTurma}
                onChange={(e) => setCodigoTurma(e.target.value)}
                placeholder="Peça o código para a catequista"
              />
            </div>
            <div style={styles.formRow}>
              <label style={styles.label}>Código de catequista (opcional)</label>
              <input style={styles.input} value={codigo} onChange={(e) => setCodigo(e.target.value)} placeholder="Deixe em branco se você é aluno" />
            </div>
          </>
        )}

        {erro && <p style={styles.loginErro}>{erro}</p>}

        <button style={styles.loginButton} disabled={carregando} onClick={mode === "entrar" ? entrar : cadastrar}>
          <Lock size={14} /> {carregando ? "Aguarde..." : mode === "entrar" ? "Entrar" : "Criar conta e entrar"}
        </button>

        <p style={styles.loginNote}>
          Login protegido pelo Firebase — você pode redefinir sua senha por e-mail a qualquer momento.
        </p>
      </div>
    </div>
  );
}

function Header({ session, onLogout, tab, setTab, tabs, previewRole, setPreviewRole, role, turmas, turmaAtualId, setTurmaAtualId, criarTurma, renomearTurma }) {
  const [criando, setCriando] = useState(false);
  const [nomeNovaTurma, setNomeNovaTurma] = useState("");
  const [editando, setEditando] = useState(false);
  const [nomeEdicao, setNomeEdicao] = useState("");

  const confirmarNovaTurma = async () => {
    if (!nomeNovaTurma.trim()) return;
    await criarTurma(nomeNovaTurma);
    setNomeNovaTurma("");
    setCriando(false);
  };

  const turmaAtual = (turmas || []).find((t) => t.id === turmaAtualId);

  const iniciarEdicao = () => {
    setNomeEdicao(turmaAtual?.nome || "");
    setEditando(true);
  };

  const confirmarEdicao = async () => {
    if (!nomeEdicao.trim()) return;
    await renomearTurma(turmaAtualId, nomeEdicao);
    setEditando(false);
  };

  return (
    <header style={styles.header}>
      <div style={styles.headerTop}>
        <div style={styles.brand}>
          <img src={APP_ICON} alt="Emaús" style={styles.brandIcon} />
          <span style={styles.brandText}>Emaús</span>
        </div>
        <div style={styles.userBox}>
          <span style={styles.userName}><User size={13} /> {session.nome}</span>
          {onLogout && <button style={styles.logoutButton} onClick={onLogout}><LogOut size={13} /></button>}
        </div>
      </div>

      {role === "catequista" && turmas && (
        <div style={styles.turmaRow}>
          {editando ? (
            <>
              <input
                style={{ ...styles.input, flex: 1 }}
                value={nomeEdicao}
                onChange={(e) => setNomeEdicao(e.target.value)}
                autoFocus
              />
              <button style={styles.saveButton} onClick={confirmarEdicao}>Salvar</button>
              <button style={styles.cancelButton} onClick={() => setEditando(false)}><X size={14} /></button>
            </>
          ) : !criando ? (
            <>
              <select
                style={styles.turmaSelect}
                value={turmaAtualId || ""}
                onChange={(e) => setTurmaAtualId(e.target.value)}
              >
                {turmas.map((t) => <option key={t.id} value={t.id}>{t.nome}</option>)}
              </select>
              <button style={styles.turmaAddButton} onClick={iniciarEdicao}><Pencil size={13} /></button>
              <button style={styles.turmaAddButton} onClick={() => setCriando(true)}><Plus size={13} /> Nova turma</button>
            </>
          ) : (
            <>
              <input
                style={{ ...styles.input, flex: 1 }}
                placeholder="Ex: Turma 2027"
                value={nomeNovaTurma}
                onChange={(e) => setNomeNovaTurma(e.target.value)}
                autoFocus
              />
              <button style={styles.saveButton} onClick={confirmarNovaTurma}>Criar</button>
              <button style={styles.cancelButton} onClick={() => { setCriando(false); setNomeNovaTurma(""); }}><X size={14} /></button>
            </>
          )}
        </div>
      )}

      {previewRole && (
        <div style={styles.previewRow}>
          <span style={styles.previewLabel}>Ver como:</span>
          <div style={styles.roleToggle}>
            <button
              onClick={() => setPreviewRole("catequista")}
              style={{ ...styles.rolePill, ...(previewRole === "catequista" ? styles.rolePillActive : {}) }}
            >
              Catequista
            </button>
            <button
              onClick={() => setPreviewRole("aluno")}
              style={{ ...styles.rolePill, ...(previewRole === "aluno" ? styles.rolePillActive : {}) }}
            >
              Catecúmeno
            </button>
          </div>
        </div>
      )}
      <nav style={styles.nav}>
        {tabs.map(({ id, label, icon: Icon, badge }) => (
          <button
            key={id}
            onClick={() => setTab(id)}
            style={{ ...styles.navButton, ...(tab === id ? styles.navButtonActive : {}) }}
          >
            <span style={{ position: "relative", display: "inline-flex" }}>
              <Icon size={16} />
              {badge > 0 && <span style={styles.navBadge}>{badge > 9 ? "9+" : badge}</span>}
            </span>
            {label}
          </button>
        ))}
      </nav>
    </header>
  );
}

function Inicio({ data, setTab }) {
  const today = todayISO();
  const ordenados = [...data.encontros].sort((a, b) => (a.data || "9999").localeCompare(b.data || "9999"));
  const proximo = ordenados.find((e) => e.data >= today) || ordenados[ordenados.length - 1];
  const concluidos = ordenados.filter((e) => e.data && e.data < today).length;
  const total = ordenados.length;
  const fixados = data.avisos.filter((a) => a.fixado);

  return (
    <div style={styles.stack}>
      <section style={styles.hero}>
        <p style={styles.heroEyebrow}>CATEQUESE DE ADULTOS</p>
        <h1 style={styles.heroTitle}>Uma jornada, passo a passo,<br />rumo ao encontro com Deus.</h1>
        <div style={styles.candleRow}>
          {ordenados.map((e) => {
            const done = e.data && e.data < today;
            return (
              <span
                key={e.id}
                style={{
                  fontSize: 18,
                  lineHeight: 1,
                  display: "inline-block",
                  transform: "scaleX(-1)",
                  opacity: done ? 1 : 0.25,
                  filter: done ? "none" : "grayscale(1)",
                }}
              >
                🚶
              </span>
            );
          })}
          <span style={styles.candleLabel}>{concluidos} de {total} encontros concluídos</span>
        </div>
      </section>

      {proximo && (
        <section style={styles.card}>
          <p style={styles.cardEyebrow}>PRÓXIMO ENCONTRO</p>
          <h2 style={styles.cardTitle}>{proximo.tema}</h2>
          <div style={styles.metaRow}>
            <span style={styles.metaItem}><Calendar size={14} /> {formatDate(proximo.data)}</span>
            {proximo.local && <span style={styles.metaItem}><MapPin size={14} /> {proximo.local}</span>}
          </div>
          {proximo.observacoes && <p style={styles.cardBody}>{proximo.observacoes}</p>}
          <button style={styles.linkButton} onClick={() => setTab("cronograma")}>Ver caminhada completa →</button>
        </section>
      )}

      {fixados.length > 0 && (
        <section style={styles.card}>
          <p style={styles.cardEyebrow}>MURAL</p>
          {fixados.map((a) => (
            <div key={a.id} style={{ marginBottom: 8 }}>
              <h3 style={styles.avisoTitleSmall}><Pin size={13} style={{ marginRight: 6 }} />{a.titulo}</h3>
              <p style={styles.cardBody}>{a.texto}</p>
            </div>
          ))}
          <button style={styles.linkButton} onClick={() => setTab("avisos")}>Ver todos os avisos →</button>
        </section>
      )}
    </div>
  );
}

