function CalendarioLiturgico() {
  const hoje = new Date();
  const { segmentos, marcadorPct, totalDias, datasChave } = calcularSegmentosAno(hoje.getFullYear(), hoje);
  const meses = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];

  const legendaVista = [];
  segmentos.forEach((s) => { if (!legendaVista.some((l) => l.nome === s.nome)) legendaVista.push(s); });

  return (
    <section style={styles.card}>
      <p style={styles.cardEyebrow}>CALENDÁRIO LITÚRGICO DO ANO</p>
      <p style={{ ...styles.cardBody, marginTop: 0 }}>
        O ano inteiro, com cada tempo litúrgico em uma cor, para você visualizar onde a turma está na
        caminhada da Igreja.
      </p>
      <div style={styles.calendarioWrap}>
        <div style={{ ...styles.calendarioMarcador, left: `${marcadorPct}%` }}>
          <span style={styles.calendarioMarcadorLabel}>Você está aqui</span>
          <span style={styles.calendarioMarcadorHaste} />
        </div>
        <div style={styles.calendarioBarra}>
          {segmentos.map((s, i) => (
            <div
              key={i}
              style={{
                width: `${s.larguraPct}%`,
                background: s.cor,
                height: "100%",
              }}
              title={s.nome}
            />
          ))}
        </div>
        <div style={styles.calendarioMeses}>
          {meses.map((m) => (
            <span key={m} style={styles.calendarioMesLabel}>{m}</span>
          ))}
        </div>
      </div>

      <div style={styles.calendarioLegenda}>
        {legendaVista.map((s) => (
          <span key={s.nome} style={styles.calendarioLegendaItem}>
            <span style={{ ...styles.calendarioLegendaCor, background: s.cor }} />
            {s.nome}
          </span>
        ))}
      </div>

      <div style={styles.calendarioDatasChave}>
        <p style={styles.calendarioSubtitulo}>Datas muito importantes</p>
        {datasChave.map((d) => (
          <div key={d.nome} style={styles.calendarioDataLinha}>
            <span>{d.nome}</span>
            <span style={styles.calendarioDataValor}>{formatDate(`${d.data.getFullYear()}-${String(d.data.getMonth() + 1).padStart(2, "0")}-${String(d.data.getDate()).padStart(2, "0")}`)}</span>
          </div>
        ))}
      </div>
    </section>
  );
}

function Liturgia({ role }) {
  const info = calcularInfoLiturgica(new Date());
  const [ia, setIa] = useState({ loading: true, data: null, error: false });

  useEffect(() => {
    let cancelado = false;
    (async () => {
      const dataISO = todayISO();
      try {
        const cacheSnap = await getDoc(doc(db, "liturgiaCache", dataISO));
        if (cacheSnap.exists()) {
          if (!cancelado) setIa({ loading: false, data: cacheSnap.data(), error: false });
          return;
        }
        const resposta = await fetch("/api/liturgia-hoje");
        if (!resposta.ok) throw new Error("falha ao buscar liturgia");
        const dados = await resposta.json();
        await setDoc(doc(db, "liturgiaCache", dataISO), dados);
        if (!cancelado) setIa({ loading: false, data: dados, error: false });
      } catch {
        if (!cancelado) setIa({ loading: false, data: null, error: true });
      }
    })();
    return () => { cancelado = true; };
  }, []);

  const celebracao = info.fixo?.nome || ia.data?.santoDoDia || "";
  const grau = info.fixo?.grau || "";

  return (
    <div style={styles.stack}>
      <div>
        <h2 style={styles.sectionTitle}>Liturgia do dia</h2>
        <p style={{ ...styles.cardBody, marginTop: 4 }}>{todayLongLabel()}</p>
      </div>

      <section style={styles.card}>
        <p style={styles.cardEyebrow}>TEMPO LITÚRGICO</p>
        <h3 style={styles.cardTitle}>{info.tempo}</h3>
        <p style={styles.cardBody}>{TEMPO_DESCRICAO[info.tempo]}</p>
        <div style={styles.metaRow}>
          <span style={styles.metaItem}>Ano litúrgico {info.anoLetra} — Evangelho de {info.evangelistaDoAno}</span>
        </div>
        <div style={styles.metaRow}>
          <span style={styles.metaItem}>Ciclo das leituras feriais: {info.cicloFerial}</span>
        </div>
      </section>

      <section style={styles.card}>
        <p style={styles.cardEyebrow}>ABSTINÊNCIA DE CARNE</p>
        <p style={styles.cardBody}>{info.abstinencia.texto}</p>
      </section>

      <section style={styles.card}>
        <p style={styles.cardEyebrow}>SANTO / CELEBRAÇÃO DO DIA</p>
        {ia.loading && !info.fixo ? (
          <p style={styles.cardBody}>Consultando o calendário…</p>
        ) : celebracao ? (
          <>
            <h3 style={styles.cardTitle}>{celebracao}</h3>
            {grau && <p style={styles.leitura}>{grau}</p>}
          </>
        ) : (
          <p style={styles.cardBody}>Hoje é dia ferial, sem memória fixa no nosso calendário.</p>
        )}
        {!info.fixo && role === "catequista" && ia.data && (
          <p style={{ ...styles.leitura, marginTop: 8 }}>
            Celebração extraída automaticamente da fonte abaixo — confirme no site oficial antes de anunciar em sala.
          </p>
        )}
      </section>

      <section style={styles.card}>
        <p style={styles.cardEyebrow}>LEITURAS DE HOJE</p>
        {ia.loading && (
          <p style={styles.cardBody}>Buscando as referências de hoje…</p>
        )}
        {ia.error && (
          <p style={styles.cardBody}>Não consegui buscar as referências agora. Use os links abaixo para ver a liturgia completa.</p>
        )}
        {ia.data?.leituras?.length > 0 && (
          <div style={{ display: "flex", flexDirection: "column", gap: 6, marginTop: 4 }}>
            {ia.data.leituras.map((l, idx) => (
              <p key={idx} style={{ ...styles.cardBody, margin: 0 }}>
                <strong style={{ color: GOLD, fontWeight: 600, marginRight: 6 }}>{l.tipo}:</strong>{l.referencia}
              </p>
            ))}
          </div>
        )}
        <p style={{ ...styles.leitura, marginTop: 10 }}>
          Mostramos só as referências (livro, capítulo e versículo) — o texto bíblico completo tem tradução
          oficial protegida por direitos autorais. Para ler o texto integral, abra um dos links abaixo.
        </p>
        <div style={styles.liturgiaLinks}>
          {ia.data?.fonte && (
            <a href={ia.data.fonte} target="_blank" rel="noopener noreferrer" style={styles.liturgiaLink}>
              <span><Sparkles size={15} /> Liturgia completa — {ia.data.fonteLabel}</span>
              <ExternalLink size={14} />
            </a>
          )}
          <a href="https://www.cnbb.org.br/liturgia-diaria/" target="_blank" rel="noopener noreferrer" style={styles.liturgiaLink}>
            <span><Sun size={15} /> Liturgia Diária — CNBB</span>
            <ExternalLink size={14} />
          </a>
          <a href="https://liturgia.cancaonova.com/pb/" target="_blank" rel="noopener noreferrer" style={styles.liturgiaLink}>
            <span><BookOpen size={15} /> Liturgia Diária — Canção Nova</span>
            <ExternalLink size={14} />
          </a>
        </div>
        {ia.data?.fonte && (
          <p style={{ ...styles.leitura, marginTop: 10, fontStyle: "italic" }}>
            Referências e santo do dia extraídos de {ia.data.fonteLabel} ({ia.data.fonte}).
          </p>
        )}
      </section>

      {role === "catequista" && (
        <section style={styles.card}>
          <p style={styles.cardEyebrow}>SUGESTÃO DE USO EM SALA</p>
          <p style={styles.cardBody}>
            Uma boa prática é abrir a leitura do Evangelho do dia no início do encontro, ler em voz alta e
            deixar um ou dois minutos de silêncio antes de comentar. É uma forma simples de conectar a turma
            com a vida da Igreja fora dos encontros.
          </p>
        </section>
      )}

      <CalendarioLiturgico />
    </div>
  );
}


function Caminhada({ users, persistUsers, session, data, persist, turmaAtualId, turmas }) {
  const me = users.find((u) => u.id === session.id);
  const [form, setForm] = useState({ ...caminhadaVazia(), ...(me?.caminhada || {}) });
  const [saved, setSaved] = useState(false);
  const [verLembranca, setVerLembranca] = useState(false);
  const [alterandoSenha, setAlterandoSenha] = useState(false);
  const [senhaAtual, setSenhaAtual] = useState("");
  const [novaSenhaPropria, setNovaSenhaPropria] = useState("");
  const [confirmarSenhaPropria, setConfirmarSenhaPropria] = useState("");
  const [erroSenhaPropria, setErroSenhaPropria] = useState("");
  const [senhaAlterada, setSenhaAlterada] = useState(false);
  const [encontroPresencaId, setEncontroPresencaId] = useState(null);

  const today = todayISO();
  const ordenados = [...data.encontros].sort((a, b) => (a.data || "9999").localeCompare(b.data || "9999"));
  const turmaEncerradaReal = ordenados.length > 0 && ordenados.every((e) => e.data && e.data < today);
  // Enquanto EXIGIR_LOGIN estiver desligado (fase de testes), libera a pré-visualização da
  // lembrança mesmo com encontros futuros na agenda, para facilitar a conferência do design.
  const turmaEncerrada = EXIGIR_LOGIN ? turmaEncerradaReal : (ordenados.length > 0 ? true : turmaEncerradaReal);

  const alterarMinhaSenha = async () => {
    setErroSenhaPropria("");
    if (!novaSenhaPropria.trim()) {
      setErroSenhaPropria("Digite a nova senha.");
      return;
    }
    if (novaSenhaPropria !== confirmarSenhaPropria) {
      setErroSenhaPropria("As senhas não conferem.");
      return;
    }
    if (novaSenhaPropria.length < 6) {
      setErroSenhaPropria("A senha precisa ter pelo menos 6 caracteres.");
      return;
    }
    try {
      const cred = EmailAuthProvider.credential(auth.currentUser.email, senhaAtual);
      await reauthenticateWithCredential(auth.currentUser, cred);
      await updatePassword(auth.currentUser, novaSenhaPropria);
      setSenhaAtual("");
      setNovaSenhaPropria("");
      setConfirmarSenhaPropria("");
      setAlterandoSenha(false);
      setSenhaAlterada(true);
      setTimeout(() => setSenhaAlterada(false), 2000);
    } catch {
      setErroSenhaPropria("Senha atual incorreta.");
    }
  };

  if (session.papel === "catequista") {
    const turmaAtual = (turmas || []).find((t) => t.id === turmaAtualId);
    const alunos = users.filter((u) => u.papel === "aluno" && u.turmaId === turmaAtualId);
    const encontrosOrdenados = [...data.encontros].sort((a, b) => (a.data || "9999").localeCompare(b.data || "9999"));
    const encontroAtual = encontrosOrdenados.find((e) => e.data === today)
      || [...encontrosOrdenados].reverse().find((e) => e.data && e.data <= today)
      || encontrosOrdenados[0]
      || null;
    const encontroPresenca = encontrosOrdenados.find((e) => e.id === encontroPresencaId) || encontroAtual;

    const marcarPresenca = (alunoId, presente) => {
      if (!encontroPresenca) return;
      const nextEncontros = data.encontros.map((e) =>
        e.id === encontroPresenca.id ? { ...e, presencas: { ...(e.presencas || {}), [alunoId]: presente } } : e
      );
      persist({ ...data, encontros: nextEncontros });
    };

    return (
      <div style={styles.stack}>
        <h2 style={styles.sectionTitle}>Caminhada da turma</h2>
        {turmaAtual?.codigoConvite && (
          <div style={styles.card}>
            <p style={styles.cardEyebrow}>CÓDIGO DE CONVITE DESTA TURMA</p>
            <p style={{ ...styles.cardTitle, fontFamily: "'Courier Prime', monospace", letterSpacing: "0.05em" }}>
              {turmaAtual.codigoConvite}
            </p>
            <p style={styles.leitura}>Compartilhe esse código com os catecúmenos — eles usam para se cadastrar nesta turma.</p>
          </div>
        )}

        <div style={styles.card}>
          <p style={styles.cardEyebrow}>PRESENÇA</p>
          {encontrosOrdenados.length === 0 ? (
            <p style={styles.emptyState}>Cadastre um encontro na aba "Caminhada" para poder registrar presença.</p>
          ) : (
            <>
              <div style={styles.formRow}>
                <label style={styles.label}>Encontro</label>
                <select
                  style={styles.input}
                  value={encontroPresenca?.id || ""}
                  onChange={(e) => setEncontroPresencaId(e.target.value)}
                >
                  {encontrosOrdenados.map((e) => (
                    <option key={e.id} value={e.id}>{formatDate(e.data)} — {e.tema}</option>
                  ))}
                </select>
              </div>
              {alunos.length === 0 && <p style={styles.emptyState}>Nenhum aluno cadastrado ainda.</p>}
              {alunos.map((a) => {
                const presente = encontroPresenca?.presencas?.[a.id];
                return (
                  <div key={a.id} style={styles.timelineHead}>
                    <span style={styles.cardBody}>{a.nome}</span>
                    <div style={styles.roleToggle}>
                      <button
                        style={{ ...styles.rolePill, ...(presente === true ? styles.rolePillActive : {}) }}
                        onClick={() => marcarPresenca(a.id, true)}
                      >
                        Presente
                      </button>
                      <button
                        style={{ ...styles.rolePill, ...(presente === false ? styles.rolePillActive : {}) }}
                        onClick={() => marcarPresenca(a.id, false)}
                      >
                        Ausente
                      </button>
                    </div>
                  </div>
                );
              })}
            </>
          )}
        </div>

        {alunos.length === 0 && <p style={styles.emptyState}>Nenhum aluno cadastrado ainda.</p>}
        {alunos.map((a) => {
          const c = a.caminhada || caminhadaVazia();
          const preenchido = c.nascimentoDia || c.batismoData || c.eucaristiaData || c.crismaData;
          return (
            <div key={a.id} style={styles.card}>
              <div style={styles.timelineHead}>
                <h3 style={styles.cardTitle}>{a.nome}</h3>
              </div>
              {!preenchido && <p style={styles.emptyState}>Ainda não preencheu a caminhada.</p>}
              {c.nascimentoDia && c.nascimentoMes && (
                <p style={styles.cardBody}>
                  Nascimento: {c.nascimentoDia} de {MESES_NOME[Number(c.nascimentoMes) - 1]}{c.nascimentoAno ? ` de ${c.nascimentoAno}` : ""}{c.nascimentoLocal ? ` — ${c.nascimentoLocal}` : ""}
                </p>
              )}
              {c.batismoData && (
                <p style={styles.cardBody}><Droplet size={13} style={{ marginRight: 4 }} />
                  Batismo: {formatDate(c.batismoData)}{c.batismoLocal ? ` — ${c.batismoLocal}` : ""}{c.padrinhos ? ` · Padrinhos: ${c.padrinhos}` : ""}
                </p>
              )}
              {c.eucaristiaData && (
                <p style={styles.cardBody}><UtensilsCrossed size={13} style={{ marginRight: 4 }} />
                  Primeira Eucaristia: {formatDate(c.eucaristiaData)}{c.eucaristiaLocal ? ` — ${c.eucaristiaLocal}` : ""}
                </p>
              )}
              {c.crismaData && (
                <p style={styles.cardBody}><Sparkles size={13} style={{ marginRight: 4 }} />
                  Crisma: {formatDate(c.crismaData)}{c.crismaLocal ? ` — ${c.crismaLocal}` : ""}{c.padrinhosCrisma ? ` · Padrinhos: ${c.padrinhosCrisma}` : ""}
                </p>
              )}
            </div>
          );
        })}
      </div>
    );
  }

  const salvar = async () => {
    const next = users.map((u) => (u.id === session.id ? { ...u, caminhada: form } : u));
    await persistUsers(next);
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  if (verLembranca) {
    return (
      <Lembranca
        nome={session.nome}
        caminhada={form}
        encontros={ordenados}
        onVoltar={() => setVerLembranca(false)}
      />
    );
  }

  return (
    <div style={styles.stack}>
      <h2 style={styles.sectionTitle}>Minha caminhada</h2>
      <p style={styles.cardBody}>
        Um espaço para registrar os passos da sua vida de fé. Todos os campos abaixo são opcionais —
        preencha só o que você já viveu e quiser compartilhar; o que faltar, pode deixar em branco.
      </p>

      <section style={styles.card}>
        <div style={styles.timelineHead}>
          <p style={{ ...styles.cardEyebrow, margin: 0 }}>MINHA CONTA</p>
          {!alterandoSenha && (
            <button style={styles.linkButton} onClick={() => { setAlterandoSenha(true); setErroSenhaPropria(""); }}>
              Alterar minha senha
            </button>
          )}
        </div>
        {(() => {
          const encontrosPassados = ordenados.filter((e) => e.data && e.data <= today);
          const minhasPresencas = encontrosPassados.filter((e) => e.autoPresencas?.[session.id]).length;
          return (
            <p style={styles.cardBody}>
              Presença que você mesmo registrou na aba "Caminhada": {minhasPresencas} de {encontrosPassados.length} encontro{encontrosPassados.length === 1 ? "" : "s"} já realizados. Essa informação é só sua — a catequista não vê essa marcação.
            </p>
          );
        })()}
        {!alterandoSenha && senhaAlterada && (
          <p style={{ ...styles.cardBody, color: GOLD }}>Senha alterada ✓</p>
        )}
        {alterandoSenha && (
          <div style={styles.formCard}>
            <div style={styles.formRow}>
              <label style={styles.label}>Senha atual</label>
              <input type="password" style={styles.input} value={senhaAtual} onChange={(e) => setSenhaAtual(e.target.value)} />
            </div>
            <div style={styles.formRow}>
              <label style={styles.label}>Nova senha</label>
              <input type="password" style={styles.input} value={novaSenhaPropria} onChange={(e) => setNovaSenhaPropria(e.target.value)} />
            </div>
            <div style={styles.formRow}>
              <label style={styles.label}>Confirmar nova senha</label>
              <input type="password" style={styles.input} value={confirmarSenhaPropria} onChange={(e) => setConfirmarSenhaPropria(e.target.value)} />
            </div>
            {erroSenhaPropria && <p style={styles.loginErro}>{erroSenhaPropria}</p>}
            <div style={styles.formActions}>
              <button
                style={styles.cancelButton}
                onClick={() => {
                  setAlterandoSenha(false);
                  setErroSenhaPropria("");
                  setSenhaAtual("");
                  setNovaSenhaPropria("");
                  setConfirmarSenhaPropria("");
                }}
              >
                <X size={14} /> Cancelar
              </button>
              <button style={styles.saveButton} onClick={alterarMinhaSenha}>Salvar nova senha</button>
            </div>
          </div>
        )}
      </section>

      {turmaEncerrada && (
        <section style={styles.card}>
          <p style={styles.cardEyebrow}>{turmaEncerradaReal ? "ESTA ETAPA SE COMPLETOU" : "PRÉ-VISUALIZAÇÃO (EM TESTES)"}</p>
          <p style={styles.cardBody}>
            {turmaEncerradaReal
              ? "Os encontros desta turma chegaram ao fim. Você pode guardar uma lembrança deste tempo, com as datas vividas e os sacramentos que já registrou."
              : "Os encontros ainda não terminaram — este link mostra como a lembrança vai aparecer quando a turma encerrar."}
          </p>
          <button style={styles.linkButton} onClick={() => setVerLembranca(true)}>Ver minha lembrança →</button>
        </section>
      )}

      <div style={styles.card}>
        <p style={styles.cardEyebrow}>MEU NASCIMENTO (OPCIONAL)</p>
        <div style={styles.formRow}>
          <label style={styles.label}>Dia</label>
          <select style={styles.input} value={form.nascimentoDia} onChange={(e) => setForm({ ...form, nascimentoDia: e.target.value })}>
            <option value="">—</option>
            {Array.from({ length: 31 }, (_, i) => i + 1).map((d) => (
              <option key={d} value={d}>{d}</option>
            ))}
          </select>
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Mês</label>
          <select style={styles.input} value={form.nascimentoMes} onChange={(e) => setForm({ ...form, nascimentoMes: e.target.value })}>
            <option value="">—</option>
            {MESES_NOME.map((m, i) => (
              <option key={m} value={i + 1}>{m}</option>
            ))}
          </select>
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Ano (opcional — deixe em branco se preferir não informar)</label>
          <input
            type="number"
            style={styles.input}
            value={form.nascimentoAno}
            onChange={(e) => setForm({ ...form, nascimentoAno: e.target.value })}
            placeholder="Ex: 1990"
          />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Local de nascimento</label>
          <input
            style={styles.input}
            value={form.nascimentoLocal}
            onChange={(e) => setForm({ ...form, nascimentoLocal: e.target.value })}
            placeholder="Cidade/estado"
          />
        </div>
        <label style={styles.checkboxRow}>
          <input
            type="checkbox"
            checked={!!form.aniversarioPublico}
            onChange={(e) => setForm({ ...form, aniversarioPublico: e.target.checked })}
          />
          Aceito que meu aniversário apareça na Comunidade da turma quando for o meu dia
        </label>
      </div>

      <div style={styles.card}>
        <p style={styles.cardEyebrow}><Droplet size={13} style={{ marginRight: 4 }} />BATISMO (OPCIONAL)</p>
        <div style={styles.formRow}>
          <label style={styles.label}>Data</label>
          <input type="date" style={styles.input} value={form.batismoData} onChange={(e) => setForm({ ...form, batismoData: e.target.value })} />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Local (paróquia/cidade)</label>
          <input style={styles.input} value={form.batismoLocal} onChange={(e) => setForm({ ...form, batismoLocal: e.target.value })} />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Padrinhos</label>
          <input style={styles.input} value={form.padrinhos} onChange={(e) => setForm({ ...form, padrinhos: e.target.value })} />
        </div>
      </div>

      <div style={styles.card}>
        <p style={styles.cardEyebrow}><UtensilsCrossed size={13} style={{ marginRight: 4 }} />PRIMEIRA EUCARISTIA (OPCIONAL)</p>
        <div style={styles.formRow}>
          <label style={styles.label}>Data</label>
          <input type="date" style={styles.input} value={form.eucaristiaData} onChange={(e) => setForm({ ...form, eucaristiaData: e.target.value })} />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Local (paróquia/cidade)</label>
          <input style={styles.input} value={form.eucaristiaLocal} onChange={(e) => setForm({ ...form, eucaristiaLocal: e.target.value })} />
        </div>
      </div>

      <div style={styles.card}>
        <p style={styles.cardEyebrow}><Sparkles size={13} style={{ marginRight: 4 }} />CRISMA (OPCIONAL)</p>
        <div style={styles.formRow}>
          <label style={styles.label}>Data</label>
          <input type="date" style={styles.input} value={form.crismaData} onChange={(e) => setForm({ ...form, crismaData: e.target.value })} />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Local (paróquia/cidade)</label>
          <input style={styles.input} value={form.crismaLocal} onChange={(e) => setForm({ ...form, crismaLocal: e.target.value })} />
        </div>
        <div style={styles.formRow}>
          <label style={styles.label}>Padrinhos</label>
          <input style={styles.input} value={form.padrinhosCrisma} onChange={(e) => setForm({ ...form, padrinhosCrisma: e.target.value })} />
        </div>
      </div>

      <button style={styles.saveButton} onClick={salvar}>{saved ? "Salvo ✓" : "Salvar minha caminhada"}</button>
    </div>
  );
}

function Lembranca({ nome, caminhada, encontros, onVoltar }) {
  const primeiro = encontros[0];
  const ultimo = encontros[encontros.length - 1];
  const hoje = new Date().toLocaleDateString("pt-BR", { day: "2-digit", month: "long", year: "numeric" });

  return (
    <div style={styles.stack}>
      <button style={styles.linkButton} onClick={onVoltar}>← Voltar</button>

      <div id="certificado-imprimir" style={styles.certificado}>
        <img src={APP_ICON} alt="Emaús" style={styles.certificadoIcon} />
        <p style={styles.certificadoEyebrow}>CATEQUESE DE ADULTOS · COMUNIDADE EMAÚS</p>
        <h2 style={styles.certificadoTitulo}>Lembrança da Primeira Etapa</h2>
        <p style={styles.certificadoNome}>{nome}</p>

        <p style={styles.certificadoTexto}>
          Guarde este registro dos encontros vividos entre {formatDate(primeiro.data)} e {formatDate(ultimo.data)},
          e das datas dos seus sacramentos — para nunca mais esquecê-las.
        </p>

        <div style={styles.certificadoSacramentos}>
          <p style={styles.certificadoSubtitulo}>Minhas datas para guardar</p>
          <p style={styles.certificadoLinha}>
            <Droplet size={13} style={{ marginRight: 5 }} />Batismo — {caminhada.batismoData ? formatDate(caminhada.batismoData) : "a preencher"}
            {caminhada.batismoLocal ? `, ${caminhada.batismoLocal}` : ""}{caminhada.padrinhos ? ` · Padrinhos: ${caminhada.padrinhos}` : ""}
          </p>
          <p style={styles.certificadoLinha}>
            <UtensilsCrossed size={13} style={{ marginRight: 5 }} />Primeira Eucaristia — {caminhada.eucaristiaData ? formatDate(caminhada.eucaristiaData) : "a preencher"}
            {caminhada.eucaristiaLocal ? `, ${caminhada.eucaristiaLocal}` : ""}
          </p>
          <p style={styles.certificadoLinha}>
            <Sparkles size={13} style={{ marginRight: 5 }} />Crisma — {caminhada.crismaData ? formatDate(caminhada.crismaData) : "a preencher"}
            {caminhada.crismaLocal ? `, ${caminhada.crismaLocal}` : ""}{caminhada.padrinhosCrisma ? ` · Padrinhos: ${caminhada.padrinhosCrisma}` : ""}
          </p>
        </div>

        <p style={styles.certificadoMensagem}>
          A caminhada continua — agora é pra valer. Estes encontros foram só o começo: a vida de fé
          se constrói todos os dias, na oração, na comunidade e no seguimento de Jesus.
        </p>

        <div style={styles.certificadoRodape}>
          <span>Emitido em {hoje}</span>
          <span style={styles.certificadoAssinatura}>Catequista responsável: ________________________</span>
        </div>
      </div>

      <button style={styles.saveButton} onClick={() => window.print()}>Imprimir / Salvar como PDF</button>
    </div>
  );
}

function Cronograma({ data, persist, role, session }) {
  const [editing, setEditing] = useState(null);
  const [form, setForm] = useState(null);
  const today = todayISO();
  const ordenadosTodos = [...data.encontros]
    .sort((a, b) => (a.data || "9999").localeCompare(b.data || "9999"))
    .map((e, i) => ({ ...e, passo: i + 1 }));
  const ordenados = role === "catequista"
    ? ordenadosTodos
    : ordenadosTodos.filter((e) => e.data && e.data <= today);
  const ocultos = ordenadosTodos.length - ordenados.length;

  const startNew = () => {
    setForm({ id: `e${Date.now()}`, numero: data.encontros.length + 1, data: "", tema: "", local: "", observacoes: "" });
    setEditing("new");
  };
  const startEdit = (e) => { setForm({ ...e }); setEditing(e.id); };
  const cancel = () => { setEditing(null); setForm(null); };

  const save = () => {
    if (!form.tema.trim()) return;
    const exists = data.encontros.some((e) => e.id === form.id);
    const next = exists
      ? data.encontros.map((e) => (e.id === form.id ? form : e))
      : [...data.encontros, form];
    persist({ ...data, encontros: next });
    cancel();
  };

  const remove = (id) => {
    persist({ ...data, encontros: data.encontros.filter((e) => e.id !== id) });
  };

  const marcarMinhaPresenca = (encontroId, presente) => {
    const next = data.encontros.map((e) =>
      e.id === encontroId ? { ...e, autoPresencas: { ...(e.autoPresencas || {}), [session.id]: presente } } : e
    );
    persist({ ...data, encontros: next });
  };

  return (
    <div style={styles.stack}>
      <div style={styles.sectionHeaderRow}>
        <h2 style={styles.sectionTitle}>Nossa Caminhada</h2>
        {role === "catequista" && (
          <button style={styles.addButton} onClick={startNew}><Plus size={15} /> Novo encontro</button>
        )}
      </div>

      {role === "aluno" && (
        <p style={styles.leitura}>
          Sua caminhada se revela passo a passo: você vê os encontros já vividos e o de hoje. Os próximos
          aparecem aqui conforme vocês forem chegando neles.
        </p>
      )}

      {editing === "new" && (
        <EncontroForm form={form} setForm={setForm} onSave={save} onCancel={cancel} />
      )}

      <div style={styles.timeline}>
        {ordenados.map((e, i) => {
          const done = e.data && e.data < today;
          return (
            <div key={e.id} style={styles.timelineItem}>
              <div style={styles.timelineMarker}>
                <div style={{ ...styles.timelineNumber, ...(done ? styles.timelineNumberDone : {}) }}>
                  {e.passo}
                </div>
                {i < ordenados.length - 1 && <div style={styles.timelineLine} />}
              </div>
              <div style={styles.timelineContent}>
                {editing === e.id ? (
                  <EncontroForm form={form} setForm={setForm} onSave={save} onCancel={cancel} />
                ) : (
                  <>
                    <div style={styles.timelineHead}>
                      <span style={styles.timelineDate}>{formatDate(e.data)}</span>
                      {role === "catequista" && (
                        <div style={styles.rowActions}>
                          <button style={styles.iconButton} onClick={() => startEdit(e)}><Pencil size={13} /></button>
                          <button style={styles.iconButton} onClick={() => remove(e.id)}><Trash2 size={13} /></button>
                        </div>
                      )}
                    </div>
                    <h3 style={styles.timelineTema}>{e.tema}</h3>
                    {e.local && <span style={styles.metaItem}><MapPin size={13} /> {e.local}</span>}
                    {e.observacoes && <p style={styles.cardBody}>{e.observacoes}</p>}
                    {e.data && (
                      <button style={styles.linkButton} onClick={() => baixarICS(e)}>
                        <Calendar size={12} style={{ marginRight: 4 }} />Adicionar ao calendário
                      </button>
                    )}
                    {role === "aluno" && (
                      <div style={{ marginTop: 6 }}>
                        <label style={styles.checkboxRow}>
                          <input
                            type="checkbox"
                            checked={!!e.autoPresencas?.[session.id]}
                            onChange={(ev) => marcarMinhaPresenca(e.id, ev.target.checked)}
                          />
                          Eu estive presente neste encontro
                        </label>
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          );
        })}
        {ordenados.length === 0 && (
          <p style={styles.emptyState}>
            {role === "aluno" ? "Sua caminhada começa no primeiro encontro. Volte aqui depois dele." : "Nenhum encontro cadastrado ainda."}
          </p>
        )}
      </div>
      {role === "aluno" && ocultos > 0 && (
        <p style={styles.emptyState}>+ {ocultos} {ocultos === 1 ? "próximo encontro será revelado" : "próximos encontros serão revelados"} conforme a turma avança.</p>
      )}
    </div>
  );
}

