function formatDateTime(iso) {
  return new Date(iso).toLocaleString("pt-BR", { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" });
}

function renderizarTexto(texto) {
  const regex = /(https?:\/\/[^\s]+|@[\wÀ-ÿ]+)/g;
  return texto.split(regex).map((parte, i) => {
    if (/^https?:\/\//.test(parte)) {
      return (
        <a key={i} href={parte} target="_blank" rel="noopener noreferrer" style={styles.postLink}>
          {parte}
        </a>
      );
    }
    if (/^@[\wÀ-ÿ]+$/.test(parte)) {
      return <span key={i} style={styles.postMencao}>{parte}</span>;
    }
    return parte;
  });
}

